package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.concurrent.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;

final class ScimAcceptance {
 static final String API="/api/openservice/directories",USER="urn:ietf:params:scim:schemas:core:2.0:User",PATCH="urn:ietf:params:scim:api:messages:2.0:PatchOp";
 static Map<String,Object> configured(WorkflowSupport h,String name,String role,List<?> groups)throws Exception {var response=h.json("POST",API,map("name",name,"role",role,"groups",groups),auth("admin"));assertEquals(201,response.statusCode(),html(response));return result(response);}
 static String path(Map<String,Object> source){return "/api/openservice/scim/"+source.get("source_id")+"/v2/Users";}
 static String bearer(Map<String,Object> source){return "Bearer "+source.get("token");}
 static Map<String,Object> user(String name,String external,boolean active){return map("schemas",List.of(USER),"userName",name,"externalId",external,"active",active);}
 static Map<String,Object> patch(boolean active){return map("schemas",List.of(PATCH),"Operations",List.of(map("op","replace","path","active","value",active)));}
 static Map<String,Object> create(WorkflowSupport h,Map<String,Object> source,String name,String external)throws Exception {var response=h.json("POST",path(source),user(name,external,true),bearer(source));assertEquals(201,response.statusCode(),html(response));var body=parsed(response);assertEquals(h.base()+path(source)+"/"+body.get("id"),response.headers().firstValue("Location").orElseThrow());assertEquals(response.headers().firstValue("Location").orElseThrow(),object(body.get("meta")).get("location"));assertTrue(response.headers().firstValue("Content-Type").orElseThrow().startsWith("application/scim+json"));assertFalse(html(response).contains("password"));return body;}
 static String group(Store store)throws Exception {try(var db=store.open()){PlatformFoundationTest.bind(db);String id=Service.create(db,"sys_user_group",map("short_description","Directory staff team"),"admin").get("sys_id").toString();db.connection.commit();return id;}}
 static void setupPassword(WorkflowSupport h,String target)throws Exception {String reset=result(h.json("POST","/api/openservice/users/"+target+"/recovery",map("current_password",PASSWORD),auth("admin"))).get("reset_path").toString();assertEquals(302,h.form(reset,map("csrf",csrf(h.get(reset,null)),"password",PASSWORD),null).statusCode());}
 static void run(WorkflowSupport h)throws Exception {
  String group=group(h.store);var s=configured(h,"Corporate directory","agent",List.of(group));var created=create(h,s,"DirectoryWorker","employee-123");String id=created.get("id").toString(),url=path(s)+"/"+id;
  assertEquals(List.of(USER),created.get("schemas"));assertEquals(true,created.get("active"));assertEquals(created,parsed(h.get(url,bearer(s))));try(var db=h.store.open()){PlatformFoundationTest.bind(db);assertEquals(1,db.count("SELECT password_reset_required FROM os_user WHERE user_id=?",id));assertEquals(1,db.count("SELECT COUNT(*) FROM os_group_member WHERE user_id=? AND group_id=?",id,group));assertEquals("agent",Service.account(db,id).get("role"));assertFalse(JSON.writeValueAsString(Scim.page(db)).contains(s.get("token").toString()));}
  setupPassword(h,id);h.login("DirectoryWorker");assertEquals(200,h.get("/account",null).statusCode());var off=h.json("PATCH",url,patch(false),bearer(s));assertEquals(200,off.statusCode(),html(off));assertEquals(false,parsed(off).get("active"));assertEquals(302,h.get("/account",null).statusCode());assertEquals(401,h.get("/api/openservice/me/profile",auth("DirectoryWorker")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_group_member WHERE user_id=?",id));}
  assertEquals(200,h.json("PUT",url,user("DirectoryWorker","employee-123",true),bearer(s)).statusCode());h.login("DirectoryWorker");assertEquals(200,h.get("/account",null).statusCode());new Store(h.environment);assertEquals(true,parsed(h.get(url,bearer(s))).get("active"));assertFalse(html(h.get(API,auth("admin"))).contains(s.get("token").toString()));try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_group_member WHERE user_id=?",id));assertEquals(1,db.count("SELECT COUNT(*) FROM os_identity WHERE user_id=?",id));assertFalse(JSON.writeValueAsString(db.all("SELECT detail FROM os_security_event")).contains(s.get("token").toString()));}
 }
 static void configuration(WorkflowSupport h)throws Exception {
  assertEquals(401,h.get(API,null).statusCode());h.account("DirectoryReader","reader");h.account("DirectoryAgent","agent");assertEquals(403,h.get(API,auth("DirectoryReader")).statusCode());assertEquals(403,h.json("POST",API,map(),auth("DirectoryAgent")).statusCode());assertEquals(405,h.json("DELETE",API,map(),auth("admin")).statusCode());assertEquals(400,h.get(API+"?x=y",auth("admin")).statusCode());assertEquals(400,h.get(API+"?x=a&x=b",auth("admin")).statusCode());assertEquals(404,h.get(API+"/"+id(),auth("admin")).statusCode());
  for(var body:List.of(map(),map("name","D","role","admin","groups",List.of()),map("name","D","role","reader","groups","bad"),map("name","D","role","reader","groups",Collections.nCopies(101,"x")),map("name","D","role","reader","groups",List.of("x","x"))))assertEquals(400,h.json("POST",API,body,auth("admin")).statusCode());assertEquals(404,h.json("POST",API,map("name","D","role","reader","groups",List.of(id())),auth("admin")).statusCode());
  var s=configured(h,"<script>Safe directory label","reader",List.of());String url=API+"/"+s.get("source_id");for(var body:List.of(map(),map("operation","remove","revision",1)))assertEquals(400,h.json("POST",url,body,auth("admin")).statusCode());assertEquals(404,h.json("POST",API+"/"+id(),map("operation","rotate","revision",1),auth("admin")).statusCode());assertEquals(409,h.json("POST",url,map("operation","rotate","revision",0),auth("admin")).statusCode());var next=result(h.json("POST",url,map("operation","rotate","revision",1),auth("admin")));assertNotEquals(s.get("token"),next.get("token"));assertEquals(401,h.get(path(s),bearer(s)).statusCode());assertEquals(200,h.get(path(next),bearer(next)).statusCode());var disabled=result(h.json("POST",url,map("operation","disable","revision",2),auth("admin")));assertEquals("",disabled.get("token"));assertEquals(401,h.get(path(next),bearer(next)).statusCode());assertEquals(200,h.json("POST",url,map("operation","rotate","revision",3),auth("admin")).statusCode());
  h.login("admin");assertEquals(403,h.form("/admin/directories",map("name","Invalid CSRF","role","reader","groups",""),null).statusCode());assertEquals(200,h.get("/admin/directories",null).statusCode());assertFalse(html(h.get("/admin/directories",null)).contains("<script>Safe directory label"));
 }
 static void authority(WorkflowSupport h)throws Exception {
  var s=configured(h,"Directory A","agent",List.of());var other=configured(h,"Directory B","reader",List.of());var created=create(h,s,"ScopedWorker","subject");String url=path(s)+"/"+created.get("id");
  for(String token:List.of("",auth("admin"),"Bearer invalid","Bearer osc_"+"x".repeat(32),bearer(other)))assertEquals(401,h.get(path(s),token).statusCode());assertEquals(401,h.get(path(s),null).statusCode());h.login("admin");assertEquals(401,h.get(path(s),null).statusCode());assertEquals(401,h.get("/api/now/table/incident",bearer(s)).statusCode());assertEquals(404,h.get(path(other)+"/"+created.get("id"),bearer(other)).statusCode());assertEquals(404,h.json("PATCH",path(other)+"/"+created.get("id"),patch(false),bearer(other)).statusCode());
  String owner;try(var db=h.store.open()){owner=RecordAccess.owner(db,"admin");db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE user_id=?",owner);db.connection.commit();}assertEquals(401,h.get(url,bearer(s)).statusCode());var renewed=result(h.json("POST",API+"/"+s.get("source_id"),map("operation","rotate","revision",1),auth("admin")));assertEquals(200,h.get(url,bearer(renewed)).statusCode());
  try(var db=h.store.open()){db.update("UPDATE os_user SET password_reset_required=1 WHERE user_id=?",owner);db.connection.commit();}assertEquals(401,h.get(url,bearer(renewed)).statusCode());try(var db=h.store.open()){db.update("UPDATE os_user SET password_reset_required=0 WHERE user_id=?",owner);db.connection.commit();}
  assertEquals(200,h.json("PATCH","/api/openservice/users/"+created.get("id")+"/role",map("role","admin"),auth("admin")).statusCode());assertEquals(403,h.json("PATCH",url,patch(false),bearer(renewed)).statusCode());assertEquals(403,h.get(path(s),bearer(renewed)).statusCode());try(var db=h.store.open()){db.update("UPDATE os_user SET role='agent',api_only=1 WHERE user_id=?",created.get("id"));db.connection.commit();}assertEquals(403,h.get(url,bearer(renewed)).statusCode());
 }
 static void identities(WorkflowSupport h)throws Exception {
  var s=configured(h,"Native isolation","requester",List.of());h.account("LocalPerson","agent");for(String name:List.of("LocalPerson","localperson","admin"))assertEquals(409,h.json("POST",path(s),user(name,"local-"+name,true),bearer(s)).statusCode());var first=create(h,s,"MappedPerson","directory-1");assertEquals(409,h.json("POST",path(s),user("AnotherPerson","directory-1",true),bearer(s)).statusCode());assertEquals("uniqueness",parsed(h.json("POST",path(s),user("MappedPerson","new",true),bearer(s))).get("scimType"));String url=path(s)+"/"+first.get("id");assertEquals(400,h.json("PUT",url,user("RenamedPerson","directory-1",true),bearer(s)).statusCode());assertEquals(400,h.json("PUT",url,user("MappedPerson","changed",true),bearer(s)).statusCode());assertEquals(404,h.get(path(s)+"/"+id(),bearer(s)).statusCode());
  var upper=map("SCHEMAS",List.of(USER),"USERNAME","UpperCasePerson","EXTERNALID","Case-2","ID","ignored","META",map("location","untrusted"));assertEquals(201,h.json("POST",path(s),upper,bearer(s)).statusCode());var inactive=parsed(h.json("POST",path(s),user("InactivePerson","inactive",false),bearer(s)));assertEquals(false,inactive.get("active"));try(var db=h.store.open()){assertEquals(0,db.count("SELECT active FROM os_user WHERE name='InactivePerson'"));assertEquals("requester",Service.account(db,first.get("id").toString()).get("role"));}
 }
 static void pagination(WorkflowSupport h)throws Exception {
  var s=configured(h,"Search","reader",List.of());var a=create(h,s,"AlphaDirectory","external \" quoted");create(h,s,"BetaDirectory","exact");var other=configured(h,"Other","reader",List.of());create(h,other,"OtherDirectory","exact");
  var list=parsed(h.get(path(s),bearer(s)));assertEquals(2,list.get("totalResults"));assertEquals(2,list.get("itemsPerPage"));assertEquals(0,parsed(h.get(path(s)+"?count=0",bearer(s))).get("itemsPerPage"));assertEquals(1,parsed(h.get(path(s)+"?startIndex=-2&count=1",bearer(s))).get("startIndex"));assertEquals(0,parsed(h.get(path(s)+"?startIndex=2000000000&count=-1",bearer(s))).get("itemsPerPage"));assertEquals(2,parsed(h.get(path(s)+"?count=200",bearer(s))).get("itemsPerPage"));
  for(var entry:Map.of("userName eq \"alphadirectory\"",a.get("id"),"externalId eq "+JSON.writeValueAsString("external \" quoted"),a.get("id")).entrySet()){var found=parsed(h.get(path(s)+"?filter="+URLEncoder.encode(entry.getKey(),StandardCharsets.UTF_8),bearer(s)));assertEquals(1,found.get("totalResults"));assertEquals(entry.getValue(),objects(found.get("Resources")).getFirst().get("id"));}
  for(String query:List.of("sortBy=userName","count=bad","filter=userName","filter=userName%20ne%20%22x%22","filter=userName%20eq%20%22%5Cq%22","filter=","count=1&count=2"))assertEquals(400,h.get(path(s)+"?"+query,bearer(s)).statusCode());assertEquals(400,h.get(path(s)+"/"+a.get("id")+"?count=1",bearer(s)).statusCode());
 }
 static void invalid(WorkflowSupport h)throws Exception {
  var s=configured(h,"Validation","agent",List.of());String url=path(s);for(var input:List.of(map(),List.of(),user("not allowed","id",true),map("schemas",List.of("bad"),"userName","Bad","externalId","id"),map("schemas",List.of(USER),"userName","Bad","externalId","id","active","true"),map("schemas",List.of(USER),"userName","Bad","externalId","id","roles",List.of("admin")),map("schemas",List.of(USER),"userName","Bad","USERNAME","Bad","externalId","id")))assertEquals(400,h.json("POST",url,input,bearer(s)).statusCode());
  for(String method:List.of("DELETE","PUT","PATCH"))assertEquals(405,h.json(method,url,map(),bearer(s)).statusCode());assertEquals(404,h.get(url.replace("Users","Groups"),bearer(s)).statusCode());assertEquals(400,h.json("POST",url+"?unexpected=1",user("Denied","id",true),bearer(s)).statusCode());assertEquals(415,h.request("POST",url,"{}".getBytes(),null,bearer(s)).statusCode());assertEquals(415,h.request("POST",url,"{}".getBytes(),"text/plain",bearer(s)).statusCode());assertEquals(400,h.request("POST",url,"{".getBytes(),"application/scim+json",bearer(s)).statusCode());assertEquals(400,h.request("POST",url,"{\"active\":true,\"active\":false}".getBytes(),"application/scim+json",bearer(s)).statusCode());assertEquals(413,h.request("POST",url,new byte[65537],"application/scim+json",bearer(s)).statusCode());
  var response=h.get(url,"Bearer bad");assertEquals("401",parsed(response).get("status"));assertEquals(List.of("urn:ietf:params:scim:api:messages:2.0:Error"),parsed(response).get("schemas"));assertTrue(response.headers().firstValue("WWW-Authenticate").orElseThrow().startsWith("Bearer"));
 }
 static void patches(WorkflowSupport h)throws Exception {
  var s=configured(h,"Patch atomicity","agent",List.of());var created=create(h,s,"PatchPerson","patch-1");String url=path(s)+"/"+created.get("id");
  for(Object body:List.of(map(),map("schemas",List.of("bad"),"Operations",List.of()),map("schemas",List.of(PATCH),"Operations","bad"),map("schemas",List.of(PATCH),"Operations",List.of()),map("schemas",List.of(PATCH),"Operations",Collections.nCopies(21,map("op","replace","path","active","value",false)))))assertEquals(400,h.json("PATCH",url,body,bearer(s)).statusCode());
  for(Object operation:List.of(map("op","remove","path","active"),map("op","replace","path","userName","value","Takeover"),map("op","replace","value",map("active",false,"role","admin")),map("op","replace","path","active","value","false"),map("op","replace","path","active","value",false,"extra",1),map("op","replace","value",List.of()))) {assertEquals(400,h.json("PATCH",url,map("schemas",List.of(PATCH),"Operations",List.of(map("op","replace","path","active","value",false),operation)),bearer(s)).statusCode());assertEquals(true,parsed(h.get(url,bearer(s))).get("active"));}
  var change=map("schemas",List.of(PATCH),"Operations",List.of(map("op","ADD","value",map("ACTIVE",false))));assertEquals(false,parsed(h.json("PATCH",url,change,bearer(s))).get("active"));assertEquals(true,parsed(h.json("PATCH",url,map("schemas",List.of(PATCH),"Operations",List.of(map("op","replace","path","ACTIVE","value",true))),bearer(s))).get("active"));assertEquals(405,h.json("POST",url,user("PatchPerson","patch-1",true),bearer(s)).statusCode());assertEquals(405,h.json("DELETE",url,map(),bearer(s)).statusCode());
 }
 static void concurrency(WorkflowSupport h)throws Exception {
  var s=configured(h,"Concurrent directory","agent",List.of());try(var pool=Executors.newFixedThreadPool(2)){var latch=new CountDownLatch(1);var one=pool.submit(()->{latch.await();return h.json("POST",path(s),user("ConcurrentPerson","same-subject",true),bearer(s)).statusCode();});var two=pool.submit(()->{latch.await();return h.json("POST",path(s),user("ConcurrentPerson","same-subject",true),bearer(s)).statusCode();});latch.countDown();assertEquals(Set.of(201,409),Set.of(one.get(),two.get()));}try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_user WHERE name='ConcurrentPerson'"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_identity"));}
 }
 static void limits(WorkflowSupport h)throws Exception {
  var s=configured(h,"Capacity","reader",List.of());try(var db=h.store.open()){var source=Scim.source(db,s.get("source_id").toString());for(int i=1;i<20;i++)db.update("INSERT INTO os_directory(source_id,name,role,definition,owner_id,owner_revision,token_hash,enabled,revision) VALUES(?,?,?,?,?,?,?,1,1)",id(),"Capacity "+i,source.get("role"),JSON.writeValueAsString(source.get("definition")),source.get("owner_id"),source.get("owner_revision"),source.get("token_hash"));for(int i=0;i<1000;i++)db.update("INSERT INTO os_identity(source,external_id,user_id) VALUES(?,?,?)","scim:"+s.get("source_id"),"external"+i,id());db.connection.commit();}assertEquals(400,h.json("POST",API,map("name","Over capacity","role","reader","groups",List.of()),auth("admin")).statusCode());assertEquals(400,h.json("POST",path(s),user("OverCapacity","new",true),bearer(s)).statusCode());
 }
 static void edges(WorkflowSupport h)throws Exception {
  String group=group(h.store);var s=configured(h,"Strict transport","reader",List.of(group));String url=path(s);
  byte[] trailing=(JSON.writeValueAsString(user("TrailingPerson","trailing",true))+" {}").getBytes(StandardCharsets.UTF_8);assertEquals(400,h.request("POST",url,trailing,"application/scim+json",bearer(s)).statusCode());
  var created=create(h,s,"StrictPerson","strict");try(var db=h.store.open()){assertEquals(Passwords.tokenHash(s.get("token").toString()),db.one("SELECT token_hash FROM os_directory WHERE source_id=?",s.get("source_id")).get("token_hash"));db.update("DELETE FROM os_record WHERE sys_id=?",group);db.connection.commit();}assertEquals(404,h.json("PATCH",url+"/"+created.get("id"),patch(false),bearer(s)).statusCode());assertEquals(true,parsed(h.get(url+"/"+created.get("id"),bearer(s))).get("active"));
  h.account("DirectoryOwner","admin");var issued=result(h.json("POST",API,map("name","Revoked owner","role","reader","groups",List.of()),auth("DirectoryOwner")));String owner;try(var db=h.store.open()){owner=RecordAccess.owner(db,"DirectoryOwner");}assertEquals(200,h.json("PATCH","/api/openservice/users/"+owner+"/role",map("role","reader"),auth("admin")).statusCode());assertEquals(401,h.get(path(issued),bearer(issued)).statusCode());
  h.account("DirectoryMachine","reader");String key;try(var db=h.store.open()){PlatformFoundationTest.bind(db);String machine=RecordAccess.owner(db,"DirectoryMachine");db.update("UPDATE os_user SET api_only=1 WHERE user_id=?",machine);key=ApiKeys.issue(db,db.viewerId,machine,map("label","Directory isolation","table","incident","days",1)).get("token").toString();db.connection.commit();}assertEquals(401,h.get(url,"Bearer "+key).statusCode());assertEquals(200,h.get("/api/now/table/incident","Bearer "+key).statusCode());
 }

}
